@page "/shipments"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Shipments Dashboard</PageTitle>

<h2 class="mb-4">📦 Shipments Dashboard</h2>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}

@if (shipments is null)
{
    <div class="d-flex align-items-center gap-2">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading shipments...</span>
    </div>
}
else if (!FilteredShipments.Any())
{
    <p class="text-muted">No shipments match your filter.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
