+        new(0, "Pending", ShipmentStatus.Pending),
+        new(1, "Picked Up", ShipmentStatus.PickedUp),
+        new(2, "In Transit", ShipmentStatus.InTransit),
+        new(3, "Out for Delivery", ShipmentStatus.OutForDelivery),
+        new(4, "Delivered", ShipmentStatus.Delivered)
+    ];
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+        {
+            await TrackShipment();
+        }
+    }
+
+    private async Task TrackShipment()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
+
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            shipment = null;
+
+            var response = await Http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
+            if (response.IsSuccessStatusCode)
+            {
+                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            }
+            else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
+            {
+                errorMessage = $"No shipment found with tracking number \"{trackingNumber}\".";
+            }
+            else if (response.StatusCode == System.Net.HttpStatusCode.Forbidden)
+            {
+                errorMessage = "You are not authorized to view this shipment.";
+            }
+            else
+            {
+                errorMessage = $"Error: {response.ReasonPhrase}";
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to track shipment: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusColor(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "secondary",
+        ShipmentStatus.PickedUp => "info",
+        ShipmentStatus.InTransit => "primary",
+        ShipmentStatus.OutForDelivery => "warning",
+        ShipmentStatus.Delivered => "success",
+        ShipmentStatus.Delayed => "danger",
+        _ => "secondary"
+    };
+
+    private static string GetStepBgColor(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Delivered => "#198754",
+        _ => "#0d6efd"
+    };
+}
