+                        <td>@s.Destination</td>
+                        <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
+                        <td>@s.ShippedDateUtc.ToString("MMM dd, yyyy")</td>
+                        <td>@s.EstimatedDeliveryUtc.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            <div class="d-flex gap-1">
+                                <select class="form-select form-select-sm" style="width: auto;"
+                                        @bind="s.Status">
+                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                                    {
+                                        <option value="@status">@status</option>
+                                    }
+                                </select>
+                                <button class="btn btn-sm btn-primary" @onclick="() => UpdateStatus(s)"
+                                        disabled="@updatingId.HasValue">
+                                    @if (updatingId == s.Id)
+                                    {
+                                        <span class="spinner-border spinner-border-sm"></span>
+                                    }
+                                    else
+                                    {
+                                        <span>Update</span>
+                                    }
+                                </button>
